def test_mgga_xc_vcml_rvv10_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_xc_vcml_rvv10", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.537451527869480e+00, -4.450996708748083e+00, -4.329900562155507e+00, -4.162252992743050e+00, -3.934024549555999e+00, -3.630723416125673e+00, -3.241339568073391e+00, -2.765762984715791e+00, -2.227845210046457e+00, -1.621069189124708e+00, -1.015307383860740e+00, -7.264188359978068e-01, -6.511882728505660e-01, -5.456408425914738e-01, -3.875295480233717e-01, -2.303759043604385e-01, -9.808304928574421e-02, -2.168796910410500e-02, -4.069886635322604e-03, -4.537192992985086e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


